<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserProfile\Domain\Gateway;

use Civi\Lughauth\Features\Access\UserProfile\Domain\UserProfile;

class UserProfileCursor
{
    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
    ) {
    }
    public function next(UserProfile $userProfile, ?int $size): UserProfileCursor
    {
        $next = clone $this;
        $next->sinceUid = $userProfile->uid();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
}
